static ITMidiMapping s_active_mapping = {
    115, 114, 117, 116, 118, 119,
    74,  71,   7,   10,  14,  15,
    0
};

void it_midi_profiles_init(void) {
}

int it_midi_profiles_get_count(void) {
    return (int)IT_ARRAY_SIZE(s_profiles);
}

const ITMidiControllerProfile* it_midi_profiles_get(int index) {
    if (index < 0 || index >= (int)IT_ARRAY_SIZE(s_profiles)) return NULL;
    return &s_profiles[index];
}

const ITMidiControllerProfile* it_midi_profiles_find_for_device(const char* device_name) {
    if (!device_name) return NULL;
    for (size_t i = 0; i < IT_ARRAY_SIZE(s_profiles); i++) {
        if (strstr(device_name, s_profiles[i].match_pattern) != NULL) {
            return &s_profiles[i];
        }
    }
    return NULL;
}

const ITMidiMapping* it_midi_profiles_get_active_mapping(void) {
    return &s_active_mapping;
}

void it_midi_profiles_set_active(int index) {
    if (index >= 0 && index < (int)IT_ARRAY_SIZE(s_profiles)) {
        s_active_mapping = s_profiles[index].mapping;
    }
}
